parameters.jsCode:
const raw = $input.first().json.text;
const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const parsed = JSON.parse(cleaned);
// normalize: handle both assigneeLids (array) and assigneeLid (singular) from LLM
if (!parsed.assigneeLids) {
  parsed.assigneeLids = parsed.assigneeLid ? [parsed.assigneeLid] : [];
}
if (!Array.isArray(parsed.assigneeLids)) {
  parsed.assigneeLids = [parsed.assigneeLids];
}
delete parsed.assigneeLid;
// stop here when the message was not a task command
if (parsed.isTask === false) {
  return [];
}
return [{ json: parsed }];

const userMapping = $('Load User Mapping').first().json.USER_MAPPING;
const mapping = Array.isArray(userMapping) ? userMapping : JSON.parse(userMapping);

const assigneeLids = $input.first().json.assigneeLids;
const lids = Array.isArray(assigneeLids) ? assigneeLids : [assigneeLids];

const users = lids.map(lid => mapping.find(u => u.lid === lid)).filter(u => u && u.user_id !== 0);

if (users.length === 0) {
  throw new Error(`No valid users found for LIDs: ${lids.join(', ')}`);
}

return [{
  json: {
    ...$input.first().json,
    user_ids: users.map(u => u.user_id),
    assignee_names: users.map(u => u.name).join(', '),
    assignee_lids: users.map(u => u.lid)
  }
}];

const projects = $input.all();
const projectList = projects.map(p => `${p.json.id}=${p.json.title}`).join(', ');
const slugMap = {};
projects.forEach(p => { slugMap[p.json.id] = p.json.slug; });
return [{ json: { projectList, slugMap } }];

const item = $('Map Assignees').first().json;
const boards = $input.all().map(i => i.json);
const inProgress = boards.find(b => b.title === 'In Progress');
const listId = inProgress ? inProgress.id : parseInt($('Load Config').first().json.LIST_ID);

// one task per assignee; assignee_lid and assignee_name are only used for the WhatsApp message
return item.user_ids.map((userId, i) => ({
  json: {
    title: item.title,
    description: item.description || '',
    project_id: parseInt(item.project_id),
    list_id: listId,
    assignee_ids: [parseInt(userId)],
    start_date: new Date().toISOString().split('T')[0],
    due_date: item.end_date,
    estimated_hours: parseFloat(item.estimation_time) || 8,
    assignee_lid: item.assignee_lids[i],
    assignee_name: item.assignee_names.split(', ')[i]
  }
}));

return $input.all().map((item, i) => ({
  json: {
    lid: $('Build Task Payloads').all()[i]?.json.assignee_lid,
    name: $('Build Task Payloads').all()[i]?.json.assignee_name,
    task_id: item.json.task?.id ?? item.json.id
  }
}));

